nextflow_process {

    name "Test Process PROPR_PROPD"
    script "../main.nf"
    process "PROPR_PROPD"

    tag "modules"
    tag "modules_nfcore"
    tag "propr"
    tag "propr/propd"
    config "./nextflow.config"

    test("Test propr/propd using default params") {

        when {
            params {
                module_args = "--round_digits 5"
            }
            process {
                """
                expression_test_data_dir = params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/'

                ch_contrasts = Channel.fromPath(file(expression_test_data_dir + 'SRP254919.contrasts.csv', checkIfExists: true))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple(it, it.variable, it.reference, it.target)
                    }
                    .first()
                ch_matrix = [
                    [id: 'test'],
                    file(expression_test_data_dir + 'SRP254919.samplesheet.csv', checkIfExists: true),
                    file(expression_test_data_dir + 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv', checkIfExists: true)
                ]

                input[0] = ch_contrasts
                input[1] = ch_matrix
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["genewise_plot", "session_info"]),
                    path(process.out.versions[0]).yaml
                ).match()}
            )
        }
    }

    test("Test propr/propd when saving all outputs") {

        when {
            params {
                module_args = "--save_pairwise_full true --save_pairwise true --save_adjacency true --save_rdata true --round_digits 5"
            }
            process {
                """
                expression_test_data_dir = params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/'

                ch_contrasts = Channel.fromPath(file(expression_test_data_dir + 'SRP254919.contrasts.csv', checkIfExists: true))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple(it, it.variable, it.reference, it.target)
                    }
                    .first()
                ch_matrix = [
                    [id: 'test'],
                    file(expression_test_data_dir + 'SRP254919.samplesheet.csv', checkIfExists: true),
                    file(expression_test_data_dir + 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv', checkIfExists: true)
                ]

                input[0] = ch_contrasts
                input[1] = ch_matrix
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["genewise_plot", "session_info", "rdata"]),
                    path(process.out.versions[0]).yaml
                ).match()}
            )
        }
    }

    test("Test propr/propd when using Box-cox transformation") {

        when {
            params {
                module_args = "--alpha 0.1 --round_digits 5"
            }
            process {
                """
                expression_test_data_dir = params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/'

                ch_contrasts = Channel.fromPath(file(expression_test_data_dir + 'SRP254919.contrasts.csv', checkIfExists: true))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple(it, it.variable, it.reference, it.target)
                    }
                    .first()
                ch_matrix = [
                    [id: 'test'],
                    file(expression_test_data_dir + 'SRP254919.samplesheet.csv', checkIfExists: true),
                    file(expression_test_data_dir + 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv', checkIfExists: true)
                ]

                input[0] = ch_contrasts
                input[1] = ch_matrix
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["genewise_plot", "session_info"]),
                    path(process.out.versions[0]).yaml
                ).match()}
            )
        }
    }

    test("Test propr/propd when using permutation tests") {

        when {
            params {
                module_args = "--permutation 10 --number_of_cutoffs 10 --seed 123 --round_digits 5"
            }
            process {
                """
                expression_test_data_dir = params.modules_testdata_base_path + 'genomics/mus_musculus/rnaseq_expression/'

                ch_contrasts = Channel.fromPath(file(expression_test_data_dir + 'SRP254919.contrasts.csv', checkIfExists: true))
                    .splitCsv ( header:true, sep:',' )
                    .map{
                        tuple(it, it.variable, it.reference, it.target)
                    }
                    .first()
                ch_matrix = [
                    [id: 'test'],
                    file(expression_test_data_dir + 'SRP254919.samplesheet.csv', checkIfExists: true),
                    file(expression_test_data_dir + 'SRP254919.salmon.merged.gene_counts.top1000cov.tsv', checkIfExists: true)
                ]

                input[0] = ch_contrasts
                input[1] = ch_matrix
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["genewise_plot", "session_info", "fdr"]),
                    path(process.out.versions[0]).yaml
                ).match()}
            )
        }
    }

    test("Test propr/propd - stub") {
        options "-stub"

        when {
            params {
                module_args = ""
            }
            process {
                """
                input[0] = [[:], '', '', '']
                input[1] = [[id: 'test'], [], []]
                """
            }
        }
        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

